import asyncioimport hashlibimport hmacimport jsonimport loggingimport osimport timeimport requestsimport websocketsfrom market_data import (    MarketDataStore,    OrderBookStore,    SymbolRanker,    TradeStore,    OrderFlowAnalyzer,    LiquidityEngine,    SignalGenerator,    SignalConfig,)from event_confirmation import EventConfirmationEngine, EventConfirmationConfigfrom bitmart_futures_client import BitMartFuturesClientfrom execution_engine import DemoFuturesExecutionEngine, ExecutionConfigfrom position_store import PositionHistoryStorelogging.basicConfig(    level=logging.INFO,    format="%(message)s",    handlers=[logging.FileHandler("bitmart_futures.log"), logging.StreamHandler()],)log = logging.getLogger()logging.getLogger("httpx").setLevel(logging.WARNING)logging.getLogger("httpcore").setLevel(logging.WARNING)DEMO_TRADING = TruePROD_PUBLIC_WS = "wss://openapi-ws-v2.bitmart.com/api?protocol=1.1"PROD_PRIVATE_WS = "wss://openapi-ws-v2.bitmart.com/user?protocol=1.1"DEMO_PUBLIC_WS = "wss://openapi-wsdemo-v2.bitmart.com/api?protocol=1.1"DEMO_PRIVATE_WS = "wss://openapi-wsdemo-v2.bitmart.com/user?protocol=1.1"PUBLIC_WS_URL = DEMO_PUBLIC_WS if DEMO_TRADING else PROD_PUBLIC_WSPRIVATE_WS_URL = DEMO_PRIVATE_WS if DEMO_TRADING else PROD_PRIVATE_WSPING_INTERVAL_SEC = 15RECONNECT_BASE_DELAY_SEC = 3RECONNECT_MAX_DELAY_SEC = 60HEARTBEAT_INTERVAL_SEC = 30TICKER_CHANNEL = "futures/ticker"DEPTH_LEVELS = 20DEPTH_CHANNEL_PREFIX = f"futures/depth{DEPTH_LEVELS}:"TRADE_CHANNEL_PREFIX = "futures/trade:"WATCHLIST_TOP_N = 15WATCHLIST_WARMUP_SEC = 10WATCHLIST_INTERVAL_SEC = 30SYMBOL_STALE_AFTER_SEC = 30TRADE_WINDOWS_MS = (500, 1000, 2000, 5000)ORDER_FLOW_INTERVAL_SEC = 0.1WHALE_SIZE_MULTIPLIER = 3.0  # a trade at/above this multiple of the window's avg size counts as a whale tradeSIGNAL_INTERVAL_SEC = 1.0POSITION_MONITOR_INTERVAL_SEC = 5.0# --- Demo Futures trade settings ---MARGIN_PER_TRADE_USDT = 1.0REQUESTED_LEVERAGE = 100MIN_LEVERAGE_REQUIRED = 50MAX_OPEN_POSITIONS = 5MAX_TOTAL_TRADES = 50TARGET_NET_PROFIT_USDT = 0.10OPEN_TYPE = "isolated"# Only act on higher-conviction signals — we're not in a rush.MIN_SIGNAL_CONFIDENCE = 0.80# Symbols the bot should never subscribe to or trade.BLACKLISTED_SYMBOLS = {"BTCUSDT"}# While scanning is paused (position cap or lifetime trade limit reached),# log a single status line at most this often instead of spamming per tick.STATUS_LOG_INTERVAL_SEC = 30.0class WatchlistState:    def __init__(self) -> None:        self.symbols = set()        # Set by run_trading_loop once the position cap is hit, so the        # watchlist/order-flow loops stop churning subscriptions and CPU on        # symbol discovery that won't be acted on anyway — only the position        # monitor keeps running and logging.        self.paused = Falsedef _load_db_config() -> dict:    here = os.path.dirname(os.path.abspath(__file__))    candidates = [        os.path.join(here, "db.txt"),        os.path.join(os.path.dirname(here), "db.txt"),    ]    for path in candidates:        if os.path.exists(path):            config = {}            with open(path, "r") as f:                for line in f:                    line = line.strip()                    if not line or line.startswith("#"):                        continue                    if "=" in line:                        k, _, v = line.partition("=")                        config[k.strip()] = v.strip().strip('"')            return config    raise FileNotFoundError(f"db.txt not found in any of: {candidates}")def _clean_secret(value):    if value is None:        return None    if isinstance(value, str):        value = value.strip()        if value.upper() in ("", "NULL"):            return None    return valuedef load_bitmart_credentials() -> dict:    from supabase import create_client    config = _load_db_config()    sb = create_client(config["SUPABASE_URL"], config["SUPABASE_KEY"])    rows = sb.table("api_keys").select("*").execute()    match = next(        (r for r in rows.data or [] if (r.get("exchange_name") or "").strip().lower() == "bitmart"),        None,    )    if not match:        raise RuntimeError("No 'BitMart' row found in the api_keys Supabase table")    api_key = _clean_secret(match.get("api_key"))    api_secret = _clean_secret(match.get("api_secret"))    memo = _clean_secret(match.get("memo"))    missing = [n for n, v in (("api_key", api_key), ("api_secret", api_secret), ("memo", memo)) if not v]    if missing:        raise RuntimeError(f"BitMart credentials incomplete in Supabase — missing: {', '.join(missing)}")    return {"api_key": api_key, "api_secret": api_secret, "memo": memo}def build_supabase_client():    """Separate client for position_history reads/writes — reuses the same    db.txt config as load_bitmart_credentials() but keeps that function's    signature (and its callers) unchanged."""    from supabase import create_client    config = _load_db_config()    return create_client(config["SUPABASE_URL"], config["SUPABASE_KEY"])def get_outbound_ip():    try:        resp = requests.get("https://api.ipify.org?format=json", timeout=5)        return resp.json().get("ip")    except Exception:        return Nonedef build_login_sign(timestamp_ms: str, memo: str, api_secret: str) -> str:    payload = f"{timestamp_ms}#{memo}#bitmart.WebSocket"    return hmac.new(api_secret.encode(), payload.encode(), hashlib.sha256).hexdigest()async def _keepalive(ws):    while True:        await asyncio.sleep(PING_INTERVAL_SEC)        try:            await ws.send(json.dumps({"action": "ping"}))        except Exception:            returnasync def _watchlist_loop(ws, ranker: SymbolRanker, order_book: OrderBookStore, trade_store: TradeStore, watchlist_state: WatchlistState):    current = set()    await asyncio.sleep(WATCHLIST_WARMUP_SEC)    while True:        if watchlist_state.paused:            # At the position cap — hold the current subscriptions as-is            # rather than churning them for symbols we won't trade anyway.            await asyncio.sleep(WATCHLIST_INTERVAL_SEC)            continue        top = set(await ranker.top_symbols()) - BLACKLISTED_SYMBOLS        added = top - current        removed = current - top        if removed:            channels = [f"{DEPTH_CHANNEL_PREFIX}{s}" for s in removed] + [f"{TRADE_CHANNEL_PREFIX}{s}" for s in removed]            await ws.send(json.dumps({"action": "unsubscribe", "args": channels}))            for symbol in removed:                await order_book.remove(symbol)                await trade_store.remove(symbol)        if added:            channels = [f"{DEPTH_CHANNEL_PREFIX}{s}" for s in added] + [f"{TRADE_CHANNEL_PREFIX}{s}" for s in added]            await ws.send(json.dumps({"action": "subscribe", "args": channels}))        if added or removed:            current = top            watchlist_state.symbols = set(current)            log.info(f"[watchlist] now tracking {sorted(current)}")        await asyncio.sleep(WATCHLIST_INTERVAL_SEC)async def run_public(market_data: MarketDataStore, order_book: OrderBookStore, ranker: SymbolRanker, trade_store: TradeStore, watchlist_state: WatchlistState):    delay = RECONNECT_BASE_DELAY_SEC    while True:        try:            log.info(f"[public] connecting to {PUBLIC_WS_URL}")            async with websockets.connect(PUBLIC_WS_URL, ping_interval=None) as ws:                log.info("[public] connected")                delay = RECONNECT_BASE_DELAY_SEC                await ws.send(json.dumps({"action": "subscribe", "args": [TICKER_CHANNEL]}))                keepalive_task = asyncio.create_task(_keepalive(ws))                watchlist_task = asyncio.create_task(_watchlist_loop(ws, ranker, order_book, trade_store, watchlist_state))                try:                    async for raw in ws:                        if raw == "pong":                            continue                        try:                            msg = json.loads(raw)                        except json.JSONDecodeError:                            log.warning(f"[public] non-JSON message: {raw[:200]}")                            continue                        group = msg.get("group", "")                        action = msg.get("action")                        if action == "subscribe":                            if msg.get("success"):                                log.info(f"[public] \u2705 subscribed to {msg.get('group')}")                            else:                                log.error(f"[public] \u274c subscribe failed: {msg}")                        elif action == "unsubscribe":                            if not msg.get("success"):                                log.error(f"[public] \u274c unsubscribe failed: {msg}")                        elif group == TICKER_CHANNEL:                            data = msg.get("data") or {}                            await market_data.update_from_ticker(data)                            await ranker.update_from_ticker(data)                        elif group.startswith(DEPTH_CHANNEL_PREFIX):                            await order_book.apply_depth_update(msg.get("data") or {})                        elif group.startswith(TRADE_CHANNEL_PREFIX):                            data = msg.get("data")                            if isinstance(data, list):                                for item in data:                                    await trade_store.apply_trade(item)                            elif isinstance(data, dict):                                await trade_store.apply_trade(data)                finally:                    keepalive_task.cancel()                    watchlist_task.cancel()        except Exception as e:            log.error(f"[public] connection error: {type(e).__name__}: {str(e)[:200]} \u2014 reconnecting in {delay}s")            await asyncio.sleep(delay)            delay = min(delay * 2, RECONNECT_MAX_DELAY_SEC)async def run_heartbeat(market_data: MarketDataStore, order_book: OrderBookStore):    while True:        await asyncio.sleep(HEARTBEAT_INTERVAL_SEC)        symbol_count = await market_data.symbol_count()        book_count = len(await order_book.symbols())        log.info(f"[heartbeat] tracking {symbol_count} tickers, {book_count} order books")async def run_order_flow(order_flow: OrderFlowAnalyzer, watchlist_state: WatchlistState):    while True:        await asyncio.sleep(ORDER_FLOW_INTERVAL_SEC)        if watchlist_state.paused:            continue        symbols = list(watchlist_state.symbols)        if symbols:            await order_flow.recompute(symbols)THIN_SEPARATOR = "-" * 40def _log_signal(signal, confirmation_result=None):    log.info(THIN_SEPARATOR)    log.info(        f"[signal] {signal.direction.upper()} {signal.symbol} "        f"confidence={signal.confidence:.2f} entry={signal.entry_price} "        f"tp={signal.take_profit:.6f} sl={signal.stop_loss:.6f}"    )    log.info(f"[signal] Prerequisites passed: {signal.prerequisites}")    log.info(f"[signal] Reasons: {signal.reasons}")    if confirmation_result is not None:        log.info(f"[signal] Confirmation: {confirmation_result.confirmations}")    log.info(THIN_SEPARATOR)async def run_trading_loop(    market_data: MarketDataStore,    signal_generator: SignalGenerator,    confirmation_engine: EventConfirmationEngine,    execution_engine: DemoFuturesExecutionEngine,    watchlist_state: WatchlistState,):    was_blocked = False    last_status_log = 0.0    while True:        await asyncio.sleep(SIGNAL_INTERVAL_SEC)        open_count = await execution_engine.open_count()        total_opened = await execution_engine.total_opened()        max_positions = execution_engine.config.max_open_positions        max_total = execution_engine.config.max_total_trades        capacity_block = open_count >= max_positions        total_block = max_total is not None and total_opened >= max_total        blocked = capacity_block or total_block        if blocked and not was_blocked:            reason = (                f"lifetime trade limit reached ({total_opened}/{max_total})"                if total_block                else f"{open_count}/{max_positions} positions open"            )            log.info(                f"[execution] {reason} — pausing signal scans and watchlist subscriptions, "                f"monitoring existing trades only"            )            last_status_log = time.time()        elif was_blocked and not blocked:            log.info(f"[execution] slot freed ({open_count}/{max_positions} open) — resuming signal scans")        was_blocked = blocked        watchlist_state.paused = blocked        if blocked:            # Beyond the one-time transition message above, surface at most            # one status line every STATUS_LOG_INTERVAL_SEC instead of            # re-evaluating (and re-logging) signals we can't act on anyway.            now = time.time()            if now - last_status_log >= STATUS_LOG_INTERVAL_SEC:                log.info(                    f"[status] {open_count}/{max_positions} open positions, "                    f"{total_opened}/{max_total} lifetime trades — monitoring only"                )                last_status_log = now            continue        for symbol in list(watchlist_state.symbols):            if symbol in BLACKLISTED_SYMBOLS:                continue            if await execution_engine.open_count() >= execution_engine.config.max_open_positions:                break            if await execution_engine.has_open_position(symbol):                continue            market = await market_data.get(symbol)            if not market:                continue            signal = await signal_generator.evaluate(symbol)            if not signal:                continue            result = await confirmation_engine.confirm(signal)            if not result.confirmed:                continue            _log_signal(signal, result)            await execution_engine.try_open_trade(signal)async def run_position_monitor(execution_engine: DemoFuturesExecutionEngine):    while True:        await asyncio.sleep(POSITION_MONITOR_INTERVAL_SEC)        try:            await execution_engine.monitor_positions()        except Exception:            log.exception("[monitor] error while monitoring open positions")async def run_shutdown_watcher(execution_engine: DemoFuturesExecutionEngine, shutdown_event: asyncio.Event):    """Once the lifetime trade cap has been reached and every trade opened    under it has closed, signal main() to stop the bot so the run can be    reviewed from position_history rather than trading indefinitely."""    while True:        await asyncio.sleep(POSITION_MONITOR_INTERVAL_SEC)        if await execution_engine.trades_exhausted():            total = await execution_engine.total_opened()            log.info(                f"[shutdown] lifetime trade limit reached ({total}/{execution_engine.config.max_total_trades}) "                f"and all positions are closed — stopping the bot for manual review of position_history"            )            shutdown_event.set()            returnasync def run_private(creds: dict):    delay = RECONNECT_BASE_DELAY_SEC    memo = creds["memo"]    while True:        try:            log.info(f"[private] connecting to {PRIVATE_WS_URL}")            async with websockets.connect(PRIVATE_WS_URL, ping_interval=None) as ws:                log.info("[private] connected \u2014 logging in")                delay = RECONNECT_BASE_DELAY_SEC                timestamp_ms = str(int(time.time() * 1000))                sign = build_login_sign(timestamp_ms, memo, creds["api_secret"])                login_msg = {"action": "access", "args": [creds["api_key"], timestamp_ms, sign, "web"]}                await ws.send(json.dumps(login_msg))                keepalive_task = asyncio.create_task(_keepalive(ws))                try:                    async for raw in ws:                        if raw == "pong":                            continue                        try:                            msg = json.loads(raw)                        except json.JSONDecodeError:                            log.warning(f"[private] non-JSON message: {raw[:200]}")                            continue                        if msg.get("action") == "access":                            if msg.get("success"):                                log.info("[private] \u2705 login successful")                            else:                                log.error(f"[private] \u274c login failed: {msg}")                                log.error("[private] if this key requires IP whitelisting, confirm this machine's outbound IP is whitelisted on BitMart")                                await asyncio.sleep(RECONNECT_MAX_DELAY_SEC)                        elif msg.get("group") == "System":                            continue                        else:                            log.info(f"[private] message: {msg}")                finally:                    keepalive_task.cancel()        except Exception as e:            log.error(f"[private] connection error: {type(e).__name__}: {str(e)[:200]} \u2014 reconnecting in {delay}s")            await asyncio.sleep(delay)            delay = min(delay * 2, RECONNECT_MAX_DELAY_SEC)async def main():    creds = load_bitmart_credentials()    outbound_ip = get_outbound_ip()    log.info(f"Outbound IP for this machine: {outbound_ip or 'could not determine'}")    log.info(f"Starting BitMart Futures bot (demo_trading={DEMO_TRADING})")    market_data = MarketDataStore()    order_book = OrderBookStore(depth_levels=DEPTH_LEVELS)    ranker = SymbolRanker(top_n=WATCHLIST_TOP_N, stale_after_sec=SYMBOL_STALE_AFTER_SEC)    trade_store = TradeStore(windows_ms=TRADE_WINDOWS_MS)    trade_store.on_unmapped_way = lambda way, payload: log.warning(f"[trade] unmapped way={way!r} — trade skipped: {payload}")    order_flow = OrderFlowAnalyzer(trade_store, windows_ms=TRADE_WINDOWS_MS, whale_size_multiplier=WHALE_SIZE_MULTIPLIER)    liquidity_engine = LiquidityEngine(order_book)    signal_generator = SignalGenerator(        market_data,        order_flow,        liquidity_engine,        order_book,        SignalConfig(            # New order-flow features — enabled            enable_aggressive_order_detection=True,            enable_whale_detection=True,            enable_trade_intensity=True,            enable_streak_detection=True,            enable_book_imbalance_by_distance=True,        ),    )    confirmation_engine = EventConfirmationEngine(        trade_store,        order_flow,        order_book,        market_data,        liquidity_engine,        EventConfirmationConfig(min_signal_confidence=MIN_SIGNAL_CONFIDENCE),    )    bitmart_client = BitMartFuturesClient(        api_key=creds["api_key"],        api_secret=creds["api_secret"],        memo=creds["memo"],        demo_trading=DEMO_TRADING,    )    position_store = None    try:        position_store = PositionHistoryStore(build_supabase_client())    except Exception:        log.exception("[position-store] could not initialize — continuing without trade persistence")    execution_engine = DemoFuturesExecutionEngine(        bitmart_client,        ExecutionConfig(            margin_per_trade_usdt=MARGIN_PER_TRADE_USDT,            requested_leverage=REQUESTED_LEVERAGE,            min_leverage_required=MIN_LEVERAGE_REQUIRED,            max_open_positions=MAX_OPEN_POSITIONS,            max_total_trades=MAX_TOTAL_TRADES,            target_net_profit_usdt=TARGET_NET_PROFIT_USDT,            open_type=OPEN_TYPE,        ),        position_store=position_store,    )    watchlist_state = WatchlistState()    shutdown_event = asyncio.Event()    tasks = [        asyncio.create_task(run_public(market_data, order_book, ranker, trade_store, watchlist_state)),        asyncio.create_task(run_private(creds)),        asyncio.create_task(run_heartbeat(market_data, order_book)),        asyncio.create_task(run_order_flow(order_flow, watchlist_state)),        asyncio.create_task(run_trading_loop(market_data, signal_generator, confirmation_engine, execution_engine, watchlist_state)),        asyncio.create_task(run_position_monitor(execution_engine)),        asyncio.create_task(run_shutdown_watcher(execution_engine, shutdown_event)),    ]    await shutdown_event.wait()    for task in tasks:        task.cancel()    await asyncio.gather(*tasks, return_exceptions=True)    log.info("[shutdown] all background tasks stopped — exiting")if __name__ == "__main__":    try:        asyncio.run(main())    except KeyboardInterrupt:        log.info("bitmart_futures.py stopped.")